1	import { Router } from "express";
2	import { db, showsTable, tasksTable, eblastsTable, todoistOrphansTable } from "@workspace/db";
3	import { eq, inArray } from "drizzle-orm";
4	import { todoistRequest, todoistListProjects, makeTodoistTask } from "../lib/todoist-client";
5	
6	const router = Router();
7	
8	type TodoistTask = { id: string };
9	
10	async function setTodoistCompletion(todoistTaskId: string, completed: boolean): Promise<void> {
11	  await todoistRequest("POST", `/api/v1/tasks/${todoistTaskId}/${completed ? "close" : "reopen"}`);
12	}
13	
14	async function syncTask(
15	  task: typeof tasksTable.$inferSelect,
16	  showName: string,
17	  projectId: string,
18	  counters: { created: number; updated: number; deleted: number },
19	) {
20	  if (!task.dueDate) {
21	    if (task.todoistTaskId) {
22	      await todoistRequest("DELETE", `/api/v1/tasks/${task.todoistTaskId}`);
23	      await db.update(tasksTable).set({ todoistTaskId: null }).where(eq(tasksTable.id, task.id));
24	      counters.deleted++;
25	    }
26	    return;
27	  }
28	
29	  const content = `${task.name} [${showName}]`;
30	  const descParts = [`Show: ${showName}`];
31	  if (task.category) descParts.push(`Category: ${task.category}`);
32	  if (task.notes) descParts.push(`Notes: ${task.notes}`);
33	  const body = makeTodoistTask(content, descParts.join("\n"), task.dueDate, projectId);
34	
35	  let todoistTaskId = task.todoistTaskId;
36	  if (todoistTaskId) {
37	    const result = await todoistRequest("POST", `/api/v1/tasks/${todoistTaskId}`, body);
38	    if (result === null) {
39	      todoistTaskId = null;
40	    } else {
41	      counters.updated++;
42	    }
43	  }
44	
45	  if (!todoistTaskId) {
46	    const created = await todoistRequest("POST", `/api/v1/tasks`, body) as TodoistTask | null;
47	    if (!created?.id) {
48	      throw new Error(
49	        `Failed to create Todoist task "${content}" — Todoist returned 404. ` +
50	        `Check that the connected Todoist account has access to the selected project.`,
51	      );
52	    }
53	    todoistTaskId = created.id;
54	    await db.update(tasksTable).set({ todoistTaskId }).where(eq(tasksTable.id, task.id));
55	    counters.created++;
56	  }
57	
58	  if (todoistTaskId) {
59	    await setTodoistCompletion(todoistTaskId, task.completed);
60	  }
61	}
62	
63	async function syncEblast(
64	  eblast: typeof eblastsTable.$inferSelect,
65	  showName: string,
66	  projectId: string,
67	  counters: { created: number; updated: number; deleted: number },
68	) {
69	  if (!eblast.dueDate) {
70	    if (eblast.todoistTaskId) {
71	      await todoistRequest("DELETE", `/api/v1/tasks/${eblast.todoistTaskId}`);
72	      await db.update(eblastsTable).set({ todoistTaskId: null }).where(eq(eblastsTable.id, eblast.id));
73	      counters.deleted++;
74	    }
75	    return;
76	  }
77	
78	  const content = `✉ ${eblast.name} [${showName}]`;
79	  const descParts = [`Show: ${showName}`, "Type: e-Blast"];
80	  if (eblast.notes) descParts.push(`Notes: ${eblast.notes}`);
81	  const body = makeTodoistTask(content, descParts.join("\n"), eblast.dueDate, projectId);
82	
83	  let todoistTaskId = eblast.todoistTaskId;
84	  if (todoistTaskId) {
85	    const result = await todoistRequest("POST", `/api/v1/tasks/${todoistTaskId}`, body);
86	    if (result === null) {
87	      todoistTaskId = null;
88	    } else {
89	      counters.updated++;
90	    }
91	  }
92	
93	  if (!todoistTaskId) {
94	    const created = await todoistRequest("POST", `/api/v1/tasks`, body) as TodoistTask | null;
95	    if (!created?.id) {
96	      throw new Error(
97	        `Failed to create Todoist task "${content}" — Todoist returned 404. ` +
98	        `Check that the connected Todoist account has access to the selected project.`,
99	      );
100	    }
101	    todoistTaskId = created.id;
102	    await db.update(eblastsTable).set({ todoistTaskId }).where(eq(eblastsTable.id, eblast.id));
103	    counters.created++;
104	  }
105	
106	  if (todoistTaskId) {
107	    await setTodoistCompletion(todoistTaskId, eblast.sent);
108	  }
109	}
110	
111	async function drainOrphans(counters: { deleted: number }) {
112	  const orphans = await db.select().from(todoistOrphansTable);
113	  if (orphans.length === 0) return;
114	
115	  const CONCURRENCY = 5;
116	  for (let i = 0; i < orphans.length; i += CONCURRENCY) {
117	    await Promise.all(
118	      orphans.slice(i, i + CONCURRENCY).map(async (orphan) => {
119	        await todoistRequest("DELETE", `/api/v1/tasks/${orphan.todoistTaskId}`);
120	        await db.delete(todoistOrphansTable).where(eq(todoistOrphansTable.id, orphan.id));
121	        counters.deleted++;
122	      }),
123	    );
124	  }
125	}
126	
127	router.get("/projects", async (_req, res): Promise<void> => {
128	  try {
129	    const projects = await todoistListProjects();
130	    res.json({ projects });
131	  } catch (err) {
132	    res.status(503).json({ error: (err as Error).message });
133	  }
134	});
135	
136	router.post("/sync", async (req, res): Promise<void> => {
137	  const taskProjectId = typeof req.query.taskProjectId === "string" ? req.query.taskProjectId : "";
138	  const eblastProjectId = typeof req.query.eblastProjectId === "string" ? req.query.eblastProjectId : "";
139	
140	  const rawShowId = req.query.showId;
141	  let showId: number | undefined;
142	  if (rawShowId !== undefined) {
143	    const parsed = Number(rawShowId);
144	    if (!Number.isInteger(parsed) || parsed <= 0) {
145	      res.status(400).json({ error: "Invalid showId — must be a positive integer" });
146	      return;
147	    }
148	    showId = parsed;
149	  }
150	
151	  const shows = showId
152	    ? await db.select().from(showsTable).where(eq(showsTable.id, showId))
153	    : await db.select().from(showsTable);
154	
155	  if (shows.length === 0 && showId !== undefined) {
156	    res.status(404).json({ error: "Show not found" });
157	    return;
158	  }
159	
160	  const showIds = shows.map((s) => s.id);
161	  const showMap = new Map(shows.map((s) => [s.id, s.name]));
162	
163	  const [allTasks, allEblasts] = await Promise.all([
164	    showIds.length > 0 ? db.select().from(tasksTable).where(inArray(tasksTable.showId, showIds)) : [],
165	    showIds.length > 0 ? db.select().from(eblastsTable).where(inArray(eblastsTable.showId, showIds)) : [],
166	  ]);
167	
168	  const counters = { created: 0, updated: 0, deleted: 0 };
169	
170	  const allWork = [
171	    ...allTasks.map((t) => () => syncTask(t, showMap.get(t.showId) ?? "", taskProjectId, counters)),
172	    ...allEblasts.map((e) => () => syncEblast(e, showMap.get(e.showId) ?? "", eblastProjectId, counters)),
173	  ];
174	
175	  const CONCURRENCY = 5;
176	  try {
177	    for (let i = 0; i < allWork.length; i += CONCURRENCY) {
178	      await Promise.all(allWork.slice(i, i + CONCURRENCY).map((fn) => fn()));
179	    }
180	    await drainOrphans(counters);
181	  } catch (err) {
182	    res.status(503).json({ error: (err as Error).message });
183	    return;
184	  }
185	
186	  res.json({ ok: true, ...counters });
187	});
188	
189	export default router;
190

