715	function computePresetDate(preset: PresetTask, show: Show): { date: string; requires: unknown } {
716	  if (!preset.dueDateOffset || !preset.dueDateUnit || !preset.dueDateDirection || !preset.dueDateAnchor) {
717	    return { date: "", requires: true };
718	  }
719	  const anchor = (show as unknown as Record<string, unknown>)[preset.dueDateAnchor];
720	  if (!anchor) return { date: "", requires: null };
721	  const anchorDate = parseDateStr(anchor as string);
722	  const d =
723	    preset.dueDateDirection === "before"
724	      ? preset.dueDateUnit === "biz"
725	        ? subBusinessDays(anchorDate, preset.dueDateOffset)
726	        : subDays(anchorDate, preset.dueDateOffset)
727	      : preset.dueDateUnit === "biz"
728	        ? addBusinessDays(anchorDate, preset.dueDateOffset)
729	        : addDays(anchorDate, preset.dueDateOffset);
730	  return { date: format(d, "yyyy-MM-dd"), requires: anchor };
731	}
